// Deployed: the build folder (index.html + assets/) uploaded to a plain static file server,
// with no rewrite rules.

// The cart lives in React context (in memory).
function Header() {
  const { items } = useCart();
  return (
    <nav>
      <a href="/cart">Cart ({items.length})</a>
    </nav>
  );
}

function ProductList({ products }) {
  const [query, setQuery] = useState("");
  const [visible, setVisible] = useState(products);

  function onSearch(q) {
    setQuery(q);
    setVisible(products.filter(p => p.name.includes(q)));
  }
  // renders <input onChange={e => onSearch(e.target.value)} /> and visible.map(...)
}

function OrderPage({ orders }) {        // orders: [{ id: 42, ... }, ...]
  const { id } = useParams();            // URL: /orders/42
  const order = orders.find(o => o.id === id);
  return order ? <OrderView order={order} /> : <p>Order not found</p>;
}

function Products() {
  const [params, setParams] = useSearchParams();
  const category = params.get("category") ?? "all";

  return (
    <select value={category}
            onChange={e => setParams({ category: e.target.value })}>
      ...
    </select>
  );
}
